// ================================================================
// LEY 2: Revisa si el post ya fue procesado antes de incluirlo
// Solo se procesa lo que realmente necesita actualización
// ================================================================

const config = $('⚙️ CONFIG').first().json;
const LABEL_PILAR = config.LABEL_PILAR.toLowerCase().trim();
const MAX_PER_GRUPO = config.MAX_CLUSTER_POR_GRUPO || 10;

const allPosts = $input.all().map(item => ({
  id:      item.json.id,
  title:   item.json.title,
  url:     item.json.url,
  labels:  (item.json.labels || []).map(l => l.toLowerCase().trim()),
  content: item.json.content || ''
}));

if (allPosts.length === 0) {
  return [{ json: { _error: 'No se encontraron posts publicados.' } }];
}

// --- Agrupar por label temática ---
// Clave del grupo: la primera label que NO sea la de pilar
const grupos = {};
for (const post of allPosts) {
  const topicLabels = post.labels.filter(l => l !== LABEL_PILAR);
  if (topicLabels.length === 0) continue;
  const key = topicLabels[0]; // primera label temática como clave de grupo
  if (!grupos[key]) grupos[key] = { pilar: null, clusters: [] };
  if (post.labels.includes(LABEL_PILAR)) {
    grupos[key].pilar = post;
  } else {
    grupos[key].clusters.push(post);
  }
}

// --- Samplear y enriquecer ---
const resultado = [];

for (const [topico, grupo] of Object.entries(grupos)) {
  if (!grupo.pilar) continue; // Skip grupos sin pilar identificado

  const pilar = grupo.pilar;

  // Shuffle de clusters para variedad en cada ejecución
  const shuffled = [...grupo.clusters].sort(() => Math.random() - 0.5);
  const seleccionados = shuffled.slice(0, MAX_PER_GRUPO);

  const enriquecer = (post, isPilar) => {
    const hasCluster = post.content.includes('<!-- CLUSTER_BLOCK -->');
    const hasCTA     = post.content.includes('<!-- CTA_BLOCK -->');

    // ⚖️ LEY 2: Si ya tiene ambos bloques → skip total
    const yaCompleto = isPilar ? hasCTA : (hasCluster && hasCTA);

    return {
      id:            post.id,
      title:         post.title,
      url:           post.url,
      labels:        post.labels,
      content:       post.content,   // Contenido original (solo para lectura)
      isPilar,
      isCluster:     !isPilar,
      pillarTitle:   isPilar ? null : pilar.title,
      pillarUrl:     isPilar ? null : pilar.url,
      topico,
      // Flags de qué bloques faltan
      needsCluster:  !isPilar && !hasCluster,
      needsCTA:      !hasCTA,
      // Flag de skip total (Ley 2)
      _skip:         yaCompleto,
      _skipReason:   yaCompleto ? 'Ya tiene ambos bloques (Ley 2)' : null,
      // Pasar config
      BLOG_ID:           config.BLOG_ID,
      DEEPSEEK_API_KEY:  config.DEEPSEEK_API_KEY,
      SYSTEME_URL:       config.SYSTEME_URL,
      BRAND_COLOR:       config.BRAND_COLOR,
      BRAND_NAME:        config.BRAND_NAME
    };
  };

  resultado.push({ json: enriquecer(pilar, true) });
  for (const cp of seleccionados) {
    resultado.push({ json: enriquecer(cp, false) });
  }
}

return resultado;

// ================================================================
// LEY 1: DeepSeek NO recibe el contenido del artículo.
// Solo recibe: título, tema/labels, datos del pilar, config de marca.
// Solo debe devolver 2 bloques HTML. Nunca el artículo original.
// ================================================================

const p = $input.item.json;

const labelsText = p.labels
  .filter(l => l !== 'pilar' && l !== 'pillar')
  .join(', ') || 'blog';

// Sistema: reglas absolutas para DeepSeek
const systemMsg =
`Eres un diseñador HTML/CSS experto en blogs y marketing de conversión en español.

⚠️ REGLAS ABSOLUTAS — sin excepciones:
1. NUNCA incluyas, reproduzcas, modifiques ni hagas referencia al contenido del artículo. No lo recibes y no lo necesitas.
2. Tu ÚNICA salida es un objeto JSON con 2 claves: clusterBlock y ctaBlock.
3. Todo el CSS debe ser 100% inline (atributo style="..."). Sin clases externas.
4. Diseños mobile-first, creativos, con emojis temáticos del nicho (NUNCA ✅❌☑️).
5. Responde ÚNICAMENTE con el JSON. Sin markdown, sin explicaciones, sin texto adicional.`;

// Usuario: datos mínimos necesarios (sin contenido del artículo)
const userMsg =
`Genera 2 bloques HTML para un post de blog con estos datos:

📝 Título del post: "${p.title}"
🏷️ Tema/nicho: ${labelsText}
${p.isCluster
  ? `📌 Tipo: CLUSTER — su pilar es: "${p.pillarTitle}" → ${p.pillarUrl}`
  : `🏆 Tipo: PILAR — (clusterBlock debe ser string vacío "")`
}
🔗 URL funnel: ${p.SYSTEME_URL}
🎨 Color de marca: ${p.BRAND_COLOR}
🏢 Nombre del sitio: ${p.BRAND_NAME}

${p.isCluster && p.needsCluster
  ? `⚡ Se necesita el clusterBlock.`
  : `ℹ️ clusterBlock = "" (no requerido para este post).`
}
${p.needsCTA
  ? `⚡ Se necesita el ctaBlock.`
  : `ℹ️ ctaBlock = "" (ya existe en el post).`
}

Responde SOLO este JSON:
{"clusterBlock": "...", "ctaBlock": "..."}

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
🔷 SPECS clusterBlock (solo si es CLUSTER y se necesita):
• Wrapper: display:flex; flex-wrap:wrap; gap:16px; align-items:center;
  background:#f0f7ff; border-left:5px solid ${p.BRAND_COLOR};
  border-radius:0 12px 12px 0; padding:20px 22px; margin:28px 0;
  box-shadow:0 2px 12px rgba(0,0,0,0.07)
• Imagen izquierda — div 78×78px:
  background: gradient 135deg variaciones del color ${p.BRAND_COLOR};
  border-radius:12px; display:flex; align-items:center;
  justify-content:center; font-size:36px; flex-shrink:0;
  pon 1 emoji ESPECÍFICO del tema "${labelsText}" (no genérico)
• Texto derecho — div flex:1; min-width:180px:
  - párrafo pequeño: font-size:0.93em; color:#374151; margin:0 0 10px;
    2 emojis del nicho + frase que diga que el pilar tiene TODO completo
    (ej: para nicho "finanzas": "💰📊 Esto es solo una parte. El panorama completo...")
  - link bold: color:${p.BRAND_COLOR}; text-decoration:none; font-weight:700;
    font-size:0.97em; href="${p.pillarUrl || ''}";
    texto: "Ver guía completa: ${p.pillarTitle || ''} →"
• Marcadores OBLIGATORIOS: empieza con <!-- CLUSTER_BLOCK --> termina con <!-- /CLUSTER_BLOCK -->
• Adaptable: en pantallas <500px el flex se envuelve (flex-wrap:wrap ya lo maneja)

━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
🔶 SPECS ctaBlock (si se necesita):
• Wrapper: background: gradient 135deg ${p.BRAND_COLOR} a su versión 20% más oscura;
  border-radius:16px; padding:32px 26px; margin:36px 0;
  text-align:center; box-shadow:0 10px 35px rgba(0,0,0,0.18);
  font-family:inherit
• Imagen superior centrada — div 88×88px inline-flex:
  border-radius:14px; background:rgba(255,255,255,0.18);
  align-items:center; justify-content:center;
  font-size:44px; margin:0 auto 18px; display:flex;
  pon 1 emoji del nicho "${labelsText}" en grande
• Título: h3 o p bold, color:#fff; font-size:1.35em; font-weight:800;
  margin:0 0 12px; 1 emoji de urgencia/valor del nicho al inicio
• 2 bullets: lista sin viñetas (ul list-style:none; padding:0; margin:0 0 22px);
  cada li: color:rgba(255,255,255,0.88); font-size:0.94em; margin:6px 0;
  emoji del nicho específico + beneficio concreto (no genérico)
• Botón CTA: a display:inline-block; background:#fff; color:${p.BRAND_COLOR};
  padding:14px 40px; border-radius:50px; font-weight:800; font-size:1.05em;
  text-decoration:none; box-shadow:0 4px 18px rgba(0,0,0,0.22);
  href="${p.SYSTEME_URL}"; texto: acción específica del nicho en imperativo
• Marcadores OBLIGATORIOS: empieza con <!-- CTA_BLOCK --> termina con <!-- /CTA_BLOCK -->`;

return {
  json: {
    ...p,
    _deepseekBody: JSON.stringify({
      model: 'deepseek-chat',
      messages: [
        { role: 'system', content: systemMsg },
        { role: 'user',   content: userMsg   }
      ],
      max_tokens: 2600,
      temperature: 0.78,
      response_format: { type: 'json_object' }
    })
  }
};

// ================================================================
// LEY 1 APLICADA EN CÓDIGO:
// - El contenido original del post NUNCA se modifica
// - Solo se AÑADEN bloques en posiciones calculadas
// - Si el marcador ya existe → se preserva el bloque existente (no se sobreescribe)
// - Se usa el contenido original del nodo 'Construir Prompt' (antes de DeepSeek)
// ================================================================

const dsResponse  = $input.item.json;
const postData    = $('🧠 Construir Prompt DeepSeek').item.json;

// --- Parsear respuesta de DeepSeek ---
let rawContent = '';
try {
  rawContent = dsResponse.choices[0].message.content || '';
} catch(e) { rawContent = ''; }

// Limpiar posible markdown
const cleaned = rawContent
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/gi, '')
  .trim();

let clusterBlock = '';
let ctaBlock     = '';

try {
  const parsed = JSON.parse(cleaned);
  clusterBlock = (parsed.clusterBlock || '').trim();
  ctaBlock     = (parsed.ctaBlock     || '').trim();
} catch(e) {
  // Fallback por marcadores
  const cm = cleaned.match(/<!-- CLUSTER_BLOCK -->[\s\S]*?<!-- \/CLUSTER_BLOCK -->/);
  const tm = cleaned.match(/<!-- CTA_BLOCK -->[\s\S]*?<!-- \/CTA_BLOCK -->/);
  clusterBlock = cm ? cm[0] : '';
  ctaBlock     = tm ? tm[0] : '';
}

// ⚖️ LEY 1: El contenido original es intocable
// Se trabaja sobre una COPIA para solo hacer operaciones de inserción
let content = postData.content; // STRING original — solo lectura hasta aquí

// --- Función de inserción segura ---
// NUNCA modifica el texto original. Solo concatena en posición segura.
function appendBlockSafe(html, originalContent, marker, position) {
  if (!html || !html.includes(marker)) return originalContent;

  // Ley 2 dentro de la inyección: si el marcador ya está en el contenido, NO hacer nada
  if (originalContent.includes(marker)) {
    return originalContent; // bloque ya existe, respetar el original
  }

  if (position === 'end') {
    return originalContent + '\n' + html;
  }

  // Para clusterBlock: insertar al 65% del artículo, después del </p> más cercano
  const cutIdx   = Math.floor(originalContent.length * 0.65);
  const anchor   = originalContent.lastIndexOf('</p>', cutIdx);
  const insertAt = anchor > 0 ? anchor + 4 : cutIdx;

  return originalContent.slice(0, insertAt) + '\n' + html + '\n' + originalContent.slice(insertAt);
}

// --- Solo insertar lo que falta (Ley 2 final) ---
if (postData.needsCluster && clusterBlock) {
  content = appendBlockSafe(clusterBlock, content, '<!-- CLUSTER_BLOCK -->', 'middle');
}

if (postData.needsCTA && ctaBlock) {
  content = appendBlockSafe(ctaBlock, content, '<!-- CTA_BLOCK -->', 'end');
}

// Verificar que algo cambió realmente
const huboInsercion = content !== postData.content;

return {
  json: {
    id:           postData.id,
    title:        postData.title,
    BLOG_ID:      postData.BLOG_ID,
    newContent:   content,
    isCluster:    postData.isCluster,
    isPilar:      postData.isPilar,
    topico:       postData.topico,
    addedCluster: postData.needsCluster && clusterBlock.length > 0,
    addedCTA:     postData.needsCTA     && ctaBlock.length > 0,
    _noChange:    !huboInsercion
  }
};

const items = $input.all();
return [{
  json: {
    status:           '✅ Blog Factory completado',
    postsAnalizados:  items.length,
    timestamp:        new Date().toLocaleString('es-MX', { timeZone: 'America/Mexico_City' }),
    nota:             `Ley 1 activa: DeepSeek nunca modificó contenido original. Ley 2 activa: posts ya procesados fueron saltados.`
  }
}];
